            except GlomError:
                raise
            except Exception as e:
                raise PathAccessError(e, _t, (i - 2) // 2)
        elif op == 'x':
            get_handler = scope[TargetRegistry].get_handler
            children = []
            _extend_children(children, cur, get_handler)
            cur = children
        elif op == 'X':
            get_handler = scope[TargetRegistry].get_handler
            result = [cur]
            queue = [cur]
