                op_map = {'+': lambda a, b: a + b, '-': lambda a, b: a - b,
                          '*': lambda a, b: a * b, '/': lambda a, b: a / b,
                          '#': lambda a, b: a // b, '%': lambda a, b: a % b,
                          ':': lambda a, b: a ** b, '&': lambda a, b: a & b,
                          '|': lambda a, b: a | b, '^': lambda a, b: a ^ b,
